arguments.content:
/**
 * Conversation Tree primitives
 *
 * Sessions are stored as trees of events: every persisted event is a node
 * (event_id, parent_id) inside a tree owned by one or more sessions. A
 * session is (tree_id, cursor_event_id) - its active conversation path.
 *
 * - Streaming chunks (message.delta / message.thinking / tool.output /
 *   tool.preparing) and queue events are ephemeral: broadcast to live WS
 *   clients but never persisted. A message is persisted once, when complete,
 *   as a single `message` event.
 * - Branching only happens at message boundaries (stable cut points that
 *   correspond to previously served LLM requests, so prefix caching stays
 *   coherent).
 * - Large tool results are externalized to the blobs table; the event
 *   payload carries {blobRef, size, preview} and the store hydrates on read.
 *
 * The tree is append-only: once a node exists its path never changes, which
 * makes path resolution results permanently cacheable.
 */

import { createHash } from 'node:crypto'
import type { Attachment, MessageSegment, MessageStats, ToolCall, ToolResult } from '../../shared/types.js'
import type { ExternalizedToolResult, StoredEvent, TurnEvent } from './types.js'

// ============================================================================
// Event classification
// ============================================================================

/**
 * Event types that are live-streaming only: pushed to WS subscribers but
 * never written to the store. Chunks are merged into the single `message`
 * event at completion; queue events are runtime state owned by the
 * session manager's in-memory queue.
 */
export const EPHEMERAL_EVENT_TYPES = new Set<string>([
  'message.delta',
  'message.thinking',
  'tool.output',
  'tool.preparing',
  'queue.added',
  'queue.drained',
  'queue.cancelled',
])

/** Event types that mark a message boundary - the only legal branch points. */
const MESSAGE_BOUNDARY_TYPES = new Set<string>(['message', 'message.start', 'message.done'])

export function isBranchPointEvent(type: string, data: unknown): boolean {
  if (!MESSAGE_BOUNDARY_TYPES.has(type)) return false
  const d = data as { messageId?: string } | null
  return typeof d?.messageId === 'string' && d.messageId.length > 0
}

// ============================================================================
// Message merge buffer (chunks -> single `message` event)
// ============================================================================

export interface MessageBufferStart {
  role: 'user' | 'assistant' | 'system'
  contextWindowId?: string
  subAgentId?: string
  subAgentType?: string
  isSystemGenerated?: boolean
  messageKind?: 'correction' | 'auto-prompt' | 'context-reset' | 'task-completed' | 'workflow-started' | 'command'
  isCompactionSummary?: boolean
  tokenCount?: number
  attachments?: Attachment[]
  metadata?: { type: string; name: string; color: string; kind?: 'definition' | 'reminder' }
}

export interface MessageBuffer {
  start: MessageBufferStart
  content: string
  thinking: string
  toolCalls: ToolCall[]
  stats?: MessageStats
  segments?: MessageSegment[]
  partial?: boolean
  tokenCount?: number
  isStreaming: boolean
  startedAt: number
}

export function createMessageBuffer(start: MessageBufferStart): MessageBuffer {
  return {
    start,
    content: '',
    thinking: '',
    toolCalls: [],
    isStreaming: true,
    startedAt: Date.now(),
  }
}

/**
 * Fold a streaming event into the buffer. Returns true when the event
 * contributed to the message (start/delta/thinking/tool.call).
 */
export function applyBufferEvent(buffer: MessageBuffer, event: TurnEvent): boolean {
  switch (event.type) {
    case 'message.delta': {
      buffer.content += event.data.content
      return true
    }
    case 'message.thinking': {
      buffer.thinking += event.data.content
      return true
    }
    case 'tool.call': {
      const existing = buffer.toolCalls.find((tc) => tc.id === event.data.toolCall.id)
      if (!existing) buffer.toolCalls.push(event.data.toolCall)
      return true
    }
    default:
      return false
  }
}

/**
 * Apply the message.done payload and mark the buffer complete.
 */
export function finalizeBuffer(buffer: MessageBuffer, event: Extract<TurnEvent, { type: 'message.done' }>): void {
  const data = event.data
  if (data.stats) buffer.stats = data.stats
  if (data.segments) buffer.segments = data.segments
  if (data.partial) buffer.partial = true
  if (data.tokenCount !== undefined) buffer.tokenCount = data.tokenCount
  buffer.isStreaming = false
}

/**
 * Merge a completed buffer into the single persisted `message` event.
 * Tool calls are stored WITHOUT results - results live in separate
 * tool.result events (so large payloads can be externalized to blobs).
 */
export function mergeBufferToMessageEvent(buffer: MessageBuffer, messageId: string): TurnEvent {
  const { start, content, thinking, toolCalls } = buffer
  const data: Record<string, unknown> = {
    messageId,
    role: start.role,
    content,
  }
  if (thinking) data.thinkingContent = thinking
  if (toolCalls.length > 0) data.toolCalls = toolCalls
  if (start.contextWindowId !== undefined) data.contextWindowId = start.contextWindowId
  if (start.subAgentId !== undefined) data.subAgentId = start.subAgentId
  if (start.subAgentType !== undefined) data.subAgentType = start.subAgentType
  if (start.isSystemGenerated !== undefined) data.isSystemGenerated = start.isSystemGenerated
  if (start.messageKind !== undefined) data.messageKind = start.messageKind
  if (start.isCompactionSummary !== undefined) data.isCompactionSummary = start.isCompactionSummary
  const tokenCount = buffer.tokenCount ?? start.tokenCount
  if (tokenCount !== undefined) data.tokenCount = tokenCount
  if (start.attachments !== undefined) data.attachments = start.attachments
  if (start.metadata !== undefined) data.metadata = start.metadata
  if (buffer.stats !== undefined) data.stats = buffer.stats
  if (buffer.segments !== undefined) data.segments = buffer.segments
  if (buffer.partial) data.partial = true
  data.isComplete = !buffer.partial
  return { type: 'message', data }
}

/**
 * Build the `message` event for a user/system message (content is known up
 * front - no merge needed).
 */
export function buildUserMessageEvent(event: Extract<TurnEvent, { type: 'message.start' }>): TurnEvent {
  const data = event.data
  const out: Record<string, unknown> = {
    messageId: data.messageId,
    role: data.role,
    content: data.content ?? '',
  }
  if (data.contextWindowId !== undefined) out.contextWindowId = data.contextWindowId
  if (data.subAgentId !== undefined) out.subAgentId = data.subAgentId
  if (data.subAgentType !== undefined) out.subAgentType = data.subAgentType
  if (data.isSystemGenerated !== undefined) out.isSystemGenerated = data.isSystemGenerated
  if (data.messageKind !== undefined) out.messageKind = data.messageKind
  if (data.isCompactionSummary !== undefined) out.isCompactionSummary = data.isCompactionSummary
  if (data.tokenCount !== undefined) out.tokenCount = data.tokenCount
  if (data.attachments !== undefined) out.attachments = data.attachments
  if (data.metadata !== undefined) out.metadata = data.metadata
  out.isComplete = true
  return { type: 'message', data }
}

/** In-flight view of a buffered message for state sync (reconnect parity). */
export function bufferToInflightMessage(buffer: MessageBuffer, messageId: string) {
  const msg: Record<string, unknown> = {
    id: messageId,
    role: buffer.start.role,
    content: buffer.content,
    timestamp: new Date(buffer.startedAt).toISOString(),
    isStreaming: true,
  }
  if (buffer.thinking) msg.thinkingContent = buffer.thinking
  if (buffer.toolCalls.length > 0) msg.toolCalls = buffer.toolCalls
  if (buffer.start.contextWindowId !== undefined) msg.contextWindowId = buffer.start.contextWindowId
  if (buffer.start.subAgentId !== undefined) msg.subAgentId = buffer.start.subAgentId
  if (buffer.start.subAgentType !== undefined) msg.subAgentType = buffer.start.subAgentType
  if (buffer.start.isSystemGenerated !== undefined) msg.isSystemGenerated = buffer.start.isSystemGenerated
  if (buffer.start.messageKind !== undefined) msg.messageKind = buffer.start.messageKind
  if (buffer.start.isCompactionSummary !== undefined) msg.isCompactionSummary = buffer.start.isCompactionSummary
  if (buffer.start.attachments !== undefined) msg.attachments = buffer.start.attachments
