export const BLOB_EXTERNALIZE_THRESHOLD = 256 * 1024
/** Head of the content kept inline as a preview. */
const BLOB_PREVIEW_BYTES = 4 * 1024

export function hashContent(content: string): string {
  return createHash('sha256').update(content, 'utf8').digest('hex')
}

function extractResultText(result: ToolResult): string {
  if (result.output) return result.output
  if (result.error) return result.error
  return JSON.stringify(result)
}

/**
 * Decide whether a tool result should be externalized and build the
 * externalized reference. Returns null when the payload fits inline.
 */
export function externalizeToolResult(result: ToolResult): ExternalizedToolResult | null {
  const serialized = JSON.stringify(result)
  if (serialized.length <= BLOB_EXTERNALIZE_THRESHOLD) return null
  const text = extractResultText(result)
  const preview = text.slice(0, BLOB_PREVIEW_BYTES)
  return {
    blobRef: hashContent(serialized),
    size: Buffer.byteLength(serialized, 'utf8'),
    preview,
    truncated: true,
  }
}

export function isExternalized(value: unknown): value is ExternalizedToolResult {
  return (
    typeof value === 'object' &&
    value !== null &&
    typeof (value as ExternalizedToolResult).blobRef === 'string' &&
    typeof (value as ExternalizedToolResult).size === 'number'
  )
}

