it('subscribers see the original chunk events, never the merged node', () => {
  insertSession(db, 's1')
  store.append('s1', { type: 'session.initialized', data: { projectId: 'p', workdir: '/w', contextWindowId: 'w1' } })
  const received: StoredEvent[] = []
  const { unsubscribe } = store.subscribe('s1')
  runAssistantTurn(store, 's1', 'a1', [
    { type: 'message.delta', data: { messageId: 'a1', content: 'hi' } },
  ])
  toolResult(store, 's1', 'a1', 'tc1', { success: true })
  unsubscribe()

  expect(received.map((e) => e.type)).toEqual(['message.start', 'message.delta', 'message.done', 'tool.result'])
  // No merged `message` event is ever pushed to live clients.
  expect(received.some((e) => e.type === 'message')).toBe(false)
})

