  seq,
  timestamp,
  event_type: event.type,
  payload,
  payloadBytes: payload.length,
})

// Sidebar counts: snapshot every session whose cursor IS the parent
// BEFORE advancing (the appending session's cursor is about to move).
let countBumpIds: string[] = []
if (event.type === 'message' && parentCursor) {
  const siblings = this.tryGetDbRows(`SELECT id FROM sessions WHERE tree_id = ?`, treeId) as {
    id: string
  }[]
  for (const sibling of siblings) {
    if (this.getCursorEventId(sibling.id) === parentCursor) {
      countBumpIds.push(sibling.id)
    }
  }
}

// Advance the session's cursor to the new node.
this.cursors.set(sessionId, eventId)
this.updateDbCursor(sessionId, eventId)
for (const id of countBumpIds) {
  this.bumpMessageCountSafe(id, 1)
}

this.promptsCache.delete(sessionId)

