      seq: 1,
      timestamp: Date.now(),
      sessionId: 'session-1',
      type: 'session.initialized',
      data: { projectId: 'proj-1', workdir: '/tmp', contextWindowId: 'window-1' },
    },
    {
      seq: 2,
      timestamp: Date.now(),
      sessionId: 'session-1',
      type: 'message',
      data: { messageId: 'msg-1', role: 'user', content: 'Hello' },
    },
    {
      seq: 3,
      timestamp: Date.now(),
      sessionId: 'session-1',
      type: 'message',
      data: { messageId: 'msg-2', role: 'assistant', content: 'Hi there!' },
    },
